// GENERATED by build.sh from extension/content.js - do not edit.
// Paste into DevTools console, Teams tab, "top" frame, filter cleared.
/*
 * Phase 0 — caption capture only.
 *
 * Purpose: prove we can read Teams live captions reliably from the DOM.
 * Deliberately does NO translation and makes NO network requests. If this phase
 * fails, the whole approach changes (we'd fall back to capturing audio and
 * running ASR ourselves), so it is worth answering on its own.
 *
 * Two problems this has to solve, and they are the real work:
 *
 *  1. FINDING the captions. Teams' markup changes and is obfuscated, so nothing
 *     here hardcodes a class name as the only strategy. We try known attributes
 *     first, then fall back to letting the user click the caption area once and
 *     remembering it. A selector we can re-point in a minute beats a clever
 *     guess that silently stops matching.
 *
 *  2. CHURN. Live ASR rewrites a line as it revises its hypothesis:
 *        "I think we should" -> "I think we should deploy"
 *        -> "I think we shouldn't deploy on Friday"
 *     Translating every revision would flicker, cost money, and sometimes invert
 *     the meaning. We only emit a segment once it has stopped changing.
 */

(() => {
  "use strict";
  if (window.__mctCleanup) { try { window.__mctCleanup(); } catch (e) {} }

  // all_frames is on, because Teams may render captions inside an iframe. Only the
  // top frame draws the panel; child frames capture and post their findings up.
  const IS_TOP = window.top === window;

  /**
   * Every repeating timer, so they can all be stopped at once.
   *
   * The extension never needs this — it loads once per page. The console build
   * does: pasting the script a second time must replace the first instance, and
   * an interval nobody kept a handle to cannot be stopped, so the old copy keeps
   * polling and translating alongside the new one.
   */
  const timers = [];
  const every = (fn, ms) => { const t = setInterval(fn, ms); timers.push(t); return t; };

  /**
   * When is a caption line finished?
   *
   * "It stopped changing for 700ms" is not the same question as "the sentence
   * ended", and conflating them is what makes the translation rewrite itself
   * under the reader. Someone says "So the pipeline" — thinks — "writes to
   * ClickHouse." The pause is longer than the settle window, so the fragment is
   * translated, then the finished sentence is translated again, and the Persian
   * changes halfway through being read.
   *
   * So: a line that ends on a full stop settles quickly, and one that does not is
   * given longer to finish before we give up and translate it anyway.
   */
  const SETTLE_MS = 700;    // ends a sentence: it is finished, translate it
  const HOLD_MS   = 2000;   // does not: wait, the speaker is probably mid-thought
  const MAX_ROWS  = 200;

  /**
   * Sentence-final punctuation, allowing a closing quote or bracket after it.
   * Includes the Arabic question mark, which Persian and Arabic captions use.
   */
  const SENTENCE_END = /[.!?\u2026\u061F]["'\u2019\u201D\u00BB)\]]?$/;

  /** Full stops that do not end a sentence: abbreviations, initials, decimals. */
  const NOT_A_STOP = /(?:\b(?:[A-Za-z]|Mr|Mrs|Ms|Dr|Prof|Sr|Jr|St|vs|etc|approx|Inc|Ltd|Fig|No)|\d)\.$/i;

  const endsSentence = (t) => SENTENCE_END.test(t) && !NOT_A_STOP.test(t);

  /**
   * Does this meeting's caption stream punctuate at all?
   *
   * Teams' ASR punctuates English well and other languages unevenly, and some
   * streams produce none. Waiting HOLD_MS for a full stop that is never coming
   * would add two seconds to every single line — trading one annoyance for a
   * worse one. So watch what actually arrives, and stop waiting if the recent
   * finished lines show no punctuation at all.
   */
  const punctHistory = [];
  const punctuates = () =>
    punctHistory.length < 6 || punctHistory.slice(-6).some(Boolean);

  // The translation companion, running on this same machine. 127.0.0.1 rather than
  // a LAN address on purpose: the service holds an API key and has no auth, and a
  // browser treats localhost as a trustworthy origin, so an https page may call it
  // without tripping mixed-content rules.
  const SERVER = "http://127.0.0.1:8100";
  const CONTEXT_N = 3;     // preceding segments sent so pronouns resolve

  /**
   * Saving the meeting to a Markdown file.
   *
   * FLUSH_MS is 60s, not the 3-5 minutes that first suggested itself. The flush is
   * a POST to a service on this same machine appending a few lines — it costs
   * nothing — and the interval is really a data-loss window: close the tab and you
   * lose whatever has not been written. A minute of a meeting is a tolerable loss;
   * five is not.
   *
   * SEAL_MS is the reason the file can be append-only. Live captions rewrite
   * themselves for a few seconds after they first appear, and translations arrive
   * a second or two after that. Writing a segment immediately would mean going
   * back to correct lines already on disk — rewriting the whole file on every
   * flush. Waiting 20 seconds instead costs nothing: you read this file after the
   * meeting, not during it.
   */
  const FLUSH_MS = 60000;
  const SEAL_MS  = 20000;
  const FLUSH_MAX = 200;   // segments per request; keepalive bodies are capped at 64KB

  /** Session id doubles as the filename stem, so it stays within [A-Za-z0-9_-].
   *  Time-first so the folder sorts chronologically; the random tail keeps two
   *  meetings started in the same minute apart. */
  const SESSION = (() => {
    const d = new Date(), p = n => String(n).padStart(2, "0");
    return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`
         + `_${p(d.getHours())}${p(d.getMinutes())}`
         + `_${Math.random().toString(36).slice(2, 6)}`;
  })();
  const STARTED_AT = new Date().toLocaleString();

  const server = {
    ok: false,
    rtl: false,
    lang: "",
    lastError: "",
    inflight: 0,
    lastMs: 0,
    transcripts: false,   // does the companion save transcripts?
  };

  /** Where the meeting is being written, and whether the last write worked. */
  const saved = { dir: "", path: "", at: 0, error: "" };

  /**
   * The reader's language — the only language anyone configures.
   *
   * Deliberately not "translate FROM x TO y". Which language a meeting is
   * captioned in belongs to the meeting, changes between meetings, and is often
   * not what anyone expects. Asking each person to keep a source language in step
   * with it guarantees that one day somebody has it wrong and reads confident
   * nonsense. So: the reader picks their own language, and the source is detected.
   */
  const prefs = { target: "" };

  /** The picker's options, from /config, cached so the picker still works offline. */
  const langs = { list: [], byCode: {} };

  /**
   * What the captions turned out to be in. Detected once per meeting from the
   * first few settled lines — see maybeDetect.
   */
  const caption = {
    lang: "",       // detected caption language, "" until it is known
    name: "",
    busy: false,    // a /detect call is in flight
    tried: false,   // one has been attempted at least once, for the UI message
    samples: [],
  };

  const LANG_KEY = "mct.target";

  const targetRow  = () => langs.byCode[prefs.target] || null;
  const targetName = () => targetRow()?.name || prefs.target || "";
  const targetRtl  = () => !!targetRow()?.rtl;
  const targetScript = () => targetRow()?.script || "latn";

  /** True when the reader already speaks the language the meeting is in, so there
   *  is nothing to translate and no second copy of each line to show. */
  const passthrough = () =>
    !!caption.lang && !!prefs.target && caption.lang === prefs.target;

  /**
   * Preferences live in extension storage when there is one, and in the page's
   * localStorage otherwise, so the console build behaves the same. Both can throw
   * or be missing; neither is worth failing to start over.
   */
  const store = {
    async get(key) {
      try {
        const api = globalThis.chrome?.storage;
        if (api) {
          const bag = await (api.sync || api.local).get(key);
          if (bag && bag[key] != null) return bag[key];
        }
      } catch (e) { /* fall through to localStorage */ }
      try { return localStorage.getItem(key) ?? null; } catch (e) { return null; }
    },
    async set(key, value) {
      try {
        const api = globalThis.chrome?.storage;
        if (api) { await (api.sync || api.local).set({ [key]: value }); return; }
      } catch (e) { /* fall through */ }
      try { localStorage.setItem(key, value); } catch (e) { /* nothing else to try */ }
    },
  };

  /** Recent English segments, for context. Kept short — the point is resolving
   *  "he"/"it"/"that", not summarising the meeting. */
  const recent = [];

  /**
   * Everything each speaker said, in order. Feeds the per-speaker summary.
   * English is stored, not the translation: summarising a translation compounds
   * whatever the translator got wrong.
   */
  const bySpeaker = new Map();   // speaker -> [text, ...]

  /**
   * Speaker colours.
   *
   * Derived from a hash of the name rather than assigned randomly, so the same
   * person keeps the same colour for the whole meeting, across a page reload, and
   * on everyone's screen. Random assignment would also occasionally pick two
   * near-identical colours for the two people talking most.
   *
   * The palette is hand-picked for legibility on the dark panel; generating hues
   * arbitrarily produces some that are unreadable against it.
   */
  const PALETTE = [
    "#60a5fa", "#f87171", "#34d399", "#fbbf24", "#c084fc",
    "#22d3ee", "#fb923c", "#a3e635", "#f472b6", "#94a3b8",
  ];
  const colorCache = new Map();
  function colorFor(name) {
    const key = (name || "").trim() || "unknown";
    if (!colorCache.has(key)) {
      let h = 0;
      for (let i = 0; i < key.length; i++) h = (h * 31 + key.charCodeAt(i)) >>> 0;
      colorCache.set(key, PALETTE[h % PALETTE.length]);
    }
    return colorCache.get(key);
  }

  /** "" means show everyone. */
  let speakerFilter = "";

  // Ordered by how much we trust them. Attribute/data hooks survive CSS churn
  // better than generated class names.
  // Confirmed against Teams web on 2026-08-29: caption text lives in
  // <span class="fui-StyledText">, inside a container whose class is generated
  // (e.g. .___18l92v8) and therefore useless as a selector.
  //
  // fui-* is Fluent UI's stable naming, so it survives far better than the hashed
  // classes around it — but it is used all over Teams, not only for captions. So we
  // look for the span, then attach to its container, rather than trusting it alone.
  const CANDIDATES = [
    '[data-tid="closed-caption-v2-window"] span.fui-StyledText',
    '[data-tid="closed-caption-v2-window"]',
    '[data-tid="closed-caption-renderer-wrapper"]',
    '[data-tid*="closed-caption"]',
    '[class*="closedCaption"]',
    '[class*="caption"]',
    '[aria-label*="aption"]',
  ];

  /**
   * Is this node part of our own UI?
   *
   * The panel displays the captions it captures, so any text search will find that
   * text inside the panel and — without this guard — attach to it. The result looks
   * plausible (rows of speakers and utterances) but it is the tool reading its own
   * output, and real captions stop arriving. Every search path must exclude it.
   */
  const isOurs = (el) => !!(el && el.closest && el.closest("#mct-panel"));

  const state = {
    container: null,
    observer: null,
    /** key -> {speaker, text, el, timer, emitted} */
    pending: new Map(),
    metaMsg: "looking for captions\u2026",
    emitted: 0,
    started: Date.now(),
  };

  // ---------- panel -------------------------------------------------------

  // Styles are injected from here rather than a separate .css file. A missing
  // stylesheet made the panel render invisibly at the bottom of the page flow —
  // a silent failure that cost an afternoon. One file, one thing to go wrong.
  const style = document.createElement("style");
  style.textContent = "#mct-panel {\n  position: fixed;\n  right: 16px;\n  bottom: 16px;\n  width: 380px;\n  max-height: 55vh;\n  display: flex;\n  flex-direction: column;\n  background: #14161c;\n  color: #e8e8ea;\n  border: 1px solid #2a2f3a;\n  border-radius: 10px;\n  font: 13px/1.5 ui-sans-serif, system-ui, sans-serif;\n  z-index: 2147483647;          /* above the page's own overlays */\n  box-shadow: 0 8px 28px rgba(0,0,0,.45);\n}\n#mct-head {\n  display: flex; align-items: center; gap: 8px;\n  padding: 8px 10px; border-bottom: 1px solid #2a2f3a;\n  font-weight: 600; cursor: move; user-select: none;\n}\n#mct-dot { width: 8px; height: 8px; border-radius: 50%; background: #6b7280; }\n#mct-dot.live { background: #34d399; }\n#mct-head .sp { flex: 1; }\n#mct-head button {\n  background: #232833; color: #e8e8ea; border: 1px solid #333a49;\n  border-radius: 6px; padding: 2px 8px; font: inherit; font-size: 12px; cursor: pointer;\n}\n#mct-log { overflow-y: auto; padding: 8px 10px; }\n.mct-seg { margin-bottom: 8px; }\n.mct-spk { color: #818cf8; font-weight: 600; font-size: 12px; }\n.mct-txt { white-space: pre-wrap; word-break: break-word; }\n.mct-live { opacity: .55; font-style: italic; }   /* still changing */\n.mct-meta { color: #7b8194; font-size: 11px; padding: 6px 10px; border-top: 1px solid #2a2f3a; }\n#mct-picking * { outline: 2px dashed #f59e0b !important; cursor: crosshair !important; }\n\n\n/* Translation lane. Persian, Arabic and Hebrew render right-to-left; without dir\n   the output is technically correct and practically unreadable. Tahoma is a safe\n   Persian face on Windows, which is what most of the team uses. */\n.mct-tr {\n  margin-top: 2px;\n  padding-left: 8px;\n  border-left: 2px solid #34d399;\n  color: #d7f5e6;\n}\n.mct-tr:empty { display: none; }\n.mct-tr.rtl {\n  direction: rtl;\n  text-align: right;\n  padding-left: 0;\n  padding-right: 8px;\n  border-left: 0;\n  border-right: 2px solid #34d399;\n  font-family: Tahoma, \"Segoe UI\", \"Noto Naskh Arabic\", sans-serif;\n  font-size: 14px;\n}\n.mct-tr.err { color: #f87171; border-color: #f87171; font-style: italic; font-size: 12px; }\n.mct-lat { font-size: 10px; color: #6b7280; margin-top: 1px; }\n.mct-lat:empty { display: none; }\n#mct-dot.warn { background: #f59e0b; }\n\n\n/* --- resizing ------------------------------------------------------------\n   Default small so it does not cover the meeting; maximised when you actually\n   need to read along. The native resize handle covers everything in between. */\n#mct-panel { resize: both; overflow: hidden; min-width: 260px; min-height: 120px; }\n#mct-panel.max { width: 620px; max-height: 82vh; }\n\n/* --- tabs ---------------------------------------------------------------- */\n.mct-tab {\n  font-size: 12px; font-weight: 600; padding: .1rem .5rem;\n  border-radius: 6px; cursor: pointer; color: var(--muted, #9096a3);\n}\n.mct-tab.on { background: #232833; color: #e8e8ea; }\n\n/* --- speaker chips: colour key and filter -------------------------------- */\n#mct-speakers {\n  display: flex; flex-wrap: wrap; gap: 4px;\n  padding: 6px 10px 0; max-height: 4.5rem; overflow-y: auto;\n}\n#mct-speakers:empty { display: none; }\n.mct-chip {\n  font-size: 11px; font-weight: 600; padding: .05rem .45rem;\n  border: 1px solid #333a49; border-radius: 20px;\n  cursor: pointer; white-space: nowrap; opacity: .65;\n}\n.mct-chip:hover { opacity: 1; }\n.mct-chip.on { opacity: 1; background: rgba(255,255,255,.07); }\n\n/* --- summary view -------------------------------------------------------- */\n#mct-summary { display: none; padding: 8px 10px; overflow-y: auto; flex: 1; }\n.mct-srow { display: flex; gap: 6px; margin-bottom: 8px; }\n.mct-srow select {\n  flex: 1; background: #14161c; color: #e8e8ea;\n  border: 1px solid #333a49; border-radius: 6px; padding: .25rem; font: inherit; font-size: 12px;\n}\n.mct-sum-out { white-space: pre-wrap; word-break: break-word; line-height: 1.6; }\n.mct-sum-out.rtl {\n  direction: rtl; text-align: right;\n  font-family: Tahoma, \"Segoe UI\", \"Noto Naskh Arabic\", sans-serif; font-size: 14px;\n}\n.mct-sum-out.err { color: #f87171; font-style: italic; }\n\n\n/* --- layout ---------------------------------------------------------------\n   The panel is a flex column. Without an explicit flex on the scrolling areas,\n   the browser sizes them from content: the log stops growing into the space it\n   has, and the chip row gets clipped mid-row so the bottom line of chips is cut\n   in half. min-height:0 is required for a flex child to be allowed to shrink\n   below its content size and scroll instead of overflowing. */\n#mct-log      { flex: 1 1 auto; min-height: 0; }\n#mct-summary  { flex: 1 1 auto; min-height: 0; flex-direction: column; }\n#mct-head     { flex: 0 0 auto; flex-wrap: wrap; }\n.mct-meta     { flex: 0 0 auto; }\n\n/* Chips wrap freely rather than scrolling inside a fixed height \u2014 a scrollable\n   box cut rows in half, which is what looked broken. */\n#mct-speakers {\n  flex: 0 0 auto;\n  max-height: none;\n  overflow: visible;\n  padding-bottom: 6px;\n}\n.mct-chip { line-height: 1.5; }\n\n\n/* Launcher pill, shown while the panel is closed. Deliberately small and dim: it\n   is a way back in, not something to look at during a meeting. */\n#mct-launcher {\n  position: fixed; right: 16px; bottom: 16px;\n  display: none;\n  background: #14161c; color: #9096a3;\n  border: 1px solid #2a2f3a; border-radius: 20px;\n  padding: .3rem .8rem;\n  font: 12px/1.4 ui-sans-serif, system-ui, sans-serif;\n  cursor: pointer; z-index: 2147483647;\n  box-shadow: 0 4px 14px rgba(0,0,0,.35);\n}\n#mct-launcher:hover { color: #e8e8ea; border-color: #3b4252; }\n\n#mct-close { color: #f87171; }\n";
  style.textContent += "\n\n/* Empty state. Opening the panel before anyone has spoken used to show a blank\n   box, which reads as broken rather than as ready. */\n#mct-log:empty::before {\n  content: \"Waiting for captions\u2026  Turn on live captions in Teams and start speaking.\";\n  display: block;\n  color: #7b8194;\n  font-style: italic;\n  padding: 10px 0;\n}\n\n/* Where the transcript is being written. Small, and directly under the status\n   line, because the question it answers (\"where is my file?\") is asked once and\n   then never again. */\n#mct-file {\n  flex: 0 0 auto;\n  padding: 0 10px 7px;\n  font-size: 11px;\n  color: #6b7280;\n  cursor: pointer;\n  word-break: break-all;\n}\n#mct-file:hover { color: #9096a3; }\n#mct-file:empty { display: none; }\n#mct-file.err { color: #f59e0b; cursor: default; }\n";
  style.textContent += "\n\n/* --- full screen ----------------------------------------------------------\n   A third size beyond \"large\", for when following the conversation IS the task\n   and the meeting behind it is not. resize is off: there is nothing to resize\n   to, and leaving the native handle on gives a grab target that does nothing. */\n#mct-panel.full {\n  left: 0; top: 0; right: 0; bottom: 0;\n  width: auto; height: auto; max-height: none;\n  border: 0; border-radius: 0;\n  resize: none;\n}\n#mct-panel.full #mct-log { padding: 12px 18px; font-size: 15px; }\n#mct-panel.full .mct-seg { margin-bottom: 14px; max-width: 90ch; }\n\n/* Way back to the newest caption after scrolling up. Floats over the log rather\n   than sitting in the layout, so appearing does not reflow what is being read. */\n#mct-jump {\n  position: absolute;\n  left: 50%;\n  transform: translateX(-50%);\n  bottom: 44px;\n  display: none;\n  background: #232833; color: #e8e8ea;\n  border: 1px solid #3b4252; border-radius: 20px;\n  padding: .2rem .7rem;\n  font-size: 11px; font-weight: 600;\n  cursor: pointer; white-space: nowrap;\n  box-shadow: 0 3px 10px rgba(0,0,0,.4);\n}\n#mct-jump:hover { border-color: #4b5563; }\n";
  style.textContent += "\n\n/* --- settings row ---------------------------------------------------------\n   Hidden behind the gear. The language picker is a set-once control, so it does\n   not earn permanent space in a 380px header -- but the current language is\n   always visible in the status line below, so the state is never hidden even\n   when the control is. The capture tools live here too: they are meaningless to\n   anyone who is not debugging a selector, and they were crowding out the things\n   people actually press. */\n#mct-settings {\n  display: none;\n  flex: 0 0 auto;\n  flex-direction: column;\n  gap: 6px;\n  padding: 8px 10px;\n  border-bottom: 1px solid #2a2f3a;\n  background: #11131a;\n}\n#mct-settings.open { display: flex; }\n#mct-settings label { font-size: 11px; color: #9096a3; display: block; margin-bottom: 3px; }\n#mct-lang {\n  width: 100%;\n  background: #14161c; color: #e8e8ea;\n  border: 1px solid #333a49; border-radius: 6px;\n  padding: .3rem; font: inherit; font-size: 13px;\n}\n#mct-detected { font-size: 11px; color: #7b8194; }\n#mct-detected b { color: #9096a3; font-weight: 600; }\n#mct-tools { display: flex; flex-wrap: wrap; gap: 4px; }\n#mct-tools button {\n  background: #232833; color: #9096a3; border: 1px solid #333a49;\n  border-radius: 6px; padding: 2px 8px; font: inherit; font-size: 11px; cursor: pointer;\n}\n#mct-tools button:hover { color: #e8e8ea; }\n\n/* --- scripts --------------------------------------------------------------\n   A font stack per writing system. The Latin defaults render Chinese, Japanese,\n   Korean, Thai and the Indic scripts as tofu or as something a reader can only\n   just make out, and CJK also breaks lines by character rather than by word --\n   so word-break has to be relaxed or every line breaks in the wrong place. */\n.mct-tr.s-arab, .mct-sum-out.s-arab {\n  font-family: Tahoma, \"Segoe UI\", \"Noto Naskh Arabic\", \"Iranian Sans\", sans-serif;\n  font-size: 14px;\n}\n.mct-tr.s-hebr, .mct-sum-out.s-hebr {\n  font-family: \"Segoe UI\", Arial, \"Noto Sans Hebrew\", sans-serif; font-size: 14px;\n}\n.mct-tr.s-hans, .mct-sum-out.s-hans,\n.mct-tr.s-hant, .mct-sum-out.s-hant {\n  font-family: \"Microsoft YaHei\", \"PingFang SC\", \"Noto Sans CJK SC\", sans-serif;\n  font-size: 15px; word-break: normal; overflow-wrap: anywhere; line-height: 1.7;\n}\n.mct-tr.s-jpan, .mct-sum-out.s-jpan {\n  font-family: \"Yu Gothic\", \"Hiragino Sans\", \"Noto Sans CJK JP\", \"Meiryo\", sans-serif;\n  font-size: 15px; word-break: normal; overflow-wrap: anywhere; line-height: 1.7;\n}\n.mct-tr.s-kore, .mct-sum-out.s-kore {\n  font-family: \"Malgun Gothic\", \"Apple SD Gothic Neo\", \"Noto Sans CJK KR\", sans-serif;\n  font-size: 15px; word-break: normal; overflow-wrap: anywhere; line-height: 1.7;\n}\n/* Thai and Khmer have no spaces between words, so a browser that breaks on\n   spaces will not break at all and the line runs off the side. */\n.mct-tr.s-thai, .mct-sum-out.s-thai {\n  font-family: \"Leelawadee UI\", \"Noto Sans Thai\", Tahoma, sans-serif;\n  font-size: 15px; word-break: break-all; line-height: 1.8;\n}\n.mct-tr.s-deva, .mct-sum-out.s-deva,\n.mct-tr.s-beng, .mct-sum-out.s-beng,\n.mct-tr.s-guru, .mct-sum-out.s-guru,\n.mct-tr.s-taml, .mct-sum-out.s-taml,\n.mct-tr.s-telu, .mct-sum-out.s-telu {\n  font-family: \"Nirmala UI\", \"Noto Sans\", sans-serif; font-size: 15px; line-height: 1.75;\n}\n.mct-tr.s-armn, .mct-sum-out.s-armn,\n.mct-tr.s-geor, .mct-sum-out.s-geor,\n.mct-tr.s-grek, .mct-sum-out.s-grek,\n.mct-tr.s-cyrl, .mct-sum-out.s-cyrl {\n  font-family: \"Segoe UI\", \"Noto Sans\", sans-serif;\n}\n\n/* Nothing to translate: the reader already speaks the meeting's language, so the\n   translation lane is not drawn at all rather than echoing each line back. */\n#mct-panel.passthrough .mct-tr,\n#mct-panel.passthrough .mct-lat { display: none; }\n";
  style.textContent += "\n\n/* A language change, marked in the flow of the conversation. Everything above it\n   is in the previous language and stays that way; everything below is in the new\n   one. Without the marker the panel just looks inconsistent. */\n.mct-note {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin: 12px 0 10px;\n  font-size: 11px;\n  color: #9096a3;\n  font-style: italic;\n}\n.mct-note::before, .mct-note::after {\n  content: \"\";\n  flex: 1;\n  height: 1px;\n  background: #2a2f3a;\n}\n.mct-note .t { font-style: normal; color: #6b7280; }\n";
  style.textContent += "\n\n/* Why there are no translations.\n   Pass-through is a correct state, and it was also completely silent: the lane\n   simply stopped appearing. Someone whose language had been switched out from\n   under them saw a tool that had broken, with a one-line status they had no\n   reason to read. It says so plainly now, and points at the way to change it. */\n#mct-why {\n  display: none;\n  flex: 0 0 auto;\n  padding: 7px 10px;\n  font-size: 11px;\n  line-height: 1.5;\n  color: #fbbf24;\n  background: rgba(251, 191, 36, .08);\n  border-bottom: 1px solid #2a2f3a;\n  cursor: pointer;\n}\n#mct-panel.why #mct-why { display: block; }\n#mct-why b { color: #fde68a; }\n";
  style.textContent += "\n\n/* A filter is hiding people.\n   It used to announce itself in the status line, which the next caption\n   overwrote a second later -- so a filter left on by a stray click was\n   invisible, and looked like the tool had stopped showing one person. Anything\n   that hides content has to keep saying so for as long as it is hiding it. */\n#mct-filtered {\n  display: none;\n  flex: 0 0 auto;\n  align-items: center;\n  gap: 8px;\n  padding: 6px 10px;\n  font-size: 11px;\n  color: #c7d2fe;\n  background: rgba(99, 102, 241, .14);\n  border-bottom: 1px solid #2a2f3a;\n}\n#mct-filtered.on { display: flex; }\n#mct-filtered .sp { flex: 1; }\n#mct-filtered button {\n  background: #232833; color: #e8e8ea; border: 1px solid #3b4252;\n  border-radius: 6px; padding: 1px 8px; font: inherit; font-size: 11px; cursor: pointer;\n}\n";
  (document.head || document.documentElement).appendChild(style);

  /**
   * Built with createElement rather than innerHTML.
   *
   * Teams sets a Trusted Types CSP (`require-trusted-types-for 'script'`), which
   * makes ANY innerHTML assignment throw:
   *   "This document requires 'TrustedHTML' assignment. The action has been blocked."
   * There is no way around it from a normal script, and no reason to want one —
   * createElement + textContent is safer anyway, and immune to the problem.
   */
  function el(tag, props = {}, kids = []) {
    const n = document.createElement(tag);
    for (const [k, v] of Object.entries(props)) {
      if (k === "text") n.textContent = v;
      else if (k === "cls") n.className = v;
      else n.setAttribute(k, v);
    }
    for (const kid of kids) n.appendChild(kid);
    return n;
  }

  const panel = el("div", { id: "mct-panel" }, [
    el("div", { id: "mct-head" }, [
      el("span", { id: "mct-dot" }),
      el("span", { id: "mct-tab-live",  cls: "mct-tab on", text: "Live" }),
      el("span", { id: "mct-tab-sum",   cls: "mct-tab",    text: "Summary" }),
      el("span", { cls: "sp" }),
      el("button", { id: "mct-copy",  text: "copy" }),
      el("button", { id: "mct-save",  text: "save", title: "write the transcript now" }),
      el("button", { id: "mct-gear",  text: "\u2699", title: "language and tools" }),
      el("button", { id: "mct-max",   text: "\u2921", title: "maximise / restore" }),
      el("button", { id: "mct-hide",  text: "\u2013", title: "collapse" }),
      el("button", { id: "mct-close", text: "\u00d7", title: "close" }),
    ]),

    // Why nothing is being translated. Only visible while that is the case.
    el("div", { id: "mct-why" }),

    // Who is being hidden. Only visible while somebody is.
    el("div", { id: "mct-filtered" }, [
      el("span", { id: "mct-filtered-txt", cls: "sp" }),
      el("button", { id: "mct-filtered-clear", text: "show everyone" }),
    ]),

    // Language, and the capture tools. Hidden until the gear is pressed.
    el("div", { id: "mct-settings" }, [
      el("div", {}, [
        el("label", { text: "Show captions in" }),
        el("select", { id: "mct-lang" }),
      ]),
      el("div", { id: "mct-detected" }),
      el("div", { id: "mct-tools" }, [
        el("button", { id: "mct-diag",  text: "find captions" }),
        el("button", { id: "mct-pick",  text: "pick manually" }),
        el("button", { id: "mct-dump",  text: "dump markup" }),
        el("button", { id: "mct-retry", text: "reconnect captions",
                       title: "find the captions again, without reloading the page" }),
      ]),
    ]),

    // Speaker chips: colour key, and the filter control. Clicking one shows only
    // that person; "All" restores the full conversation.
    el("div", { id: "mct-speakers" }),

    el("div", { id: "mct-log" }),

    // Summary view, hidden until its tab is selected.
    el("div", { id: "mct-summary" }, [
      el("div", { cls: "mct-srow" }, [
        el("select", { id: "mct-sum-who" }),
        el("button", { id: "mct-sum-go", text: "Summarise" }),
      ]),
      el("div", { id: "mct-sum-out", cls: "mct-sum-out" }),
    ]),

    el("div", { id: "mct-meta", cls: "mct-meta", text: "looking for captions\u2026" }),
    el("div", { id: "mct-file" }),
    el("div", { id: "mct-jump", text: "\u2193 jump to latest" }),
  ]);
  /**
   * Small pill shown while the panel is closed.
   *
   * Without it, closing the panel would be a one-way door: the only way back would
   * be reloading the page, which also throws away the transcript. It doubles as the
   * way in when auto-detect has not found captions yet and you need "find".
   */
  const launcher = el("div", { id: "mct-launcher", text: "\u25cf captions" });
  launcher.onclick = () => setPanelOpen(true, /*byUser=*/true);

  /**
   * Open and close only ever toggle visibility — the panel is never removed and its
   * rows are never cleared. Closing and reopening therefore keeps the whole
   * conversation, which is the point: people close it to see the meeting, not to
   * discard what was said.
   */
  let panelOpen = false;

  /**
   * Who last decided the panel should be open: nobody, or the user.
   *
   * The first version tracked only "the user closed it". Opening it from the
   * launcher therefore left no trace, so the one-second poller saw a panel open
   * with no captions on screen and shut it again — the panel flashed open and
   * vanished, which is exactly the bug this replaces. Both directions of an
   * explicit choice have to be recorded, not just one.
   *
   *   null      follow the captions
   *   "open"    the user asked for it; the poller must not close it
   *   "closed"  the user dismissed it; the poller must not reopen it
   */
  let override = null;

  function setPanelOpen(open, byUser = false) {
    panelOpen = open;
    if (byUser) override = open ? "open" : "closed";
    panel.style.display    = open ? "flex" : "none";
    launcher.style.display = open ? "none" : "block";
    if (open) toBottom();
  }

  function mountPanel() {
    if (!IS_TOP) return;
    const host = document.body || document.documentElement;
    if (!host) { setTimeout(mountPanel, 300); return; }
    if (!panel.isConnected) host.appendChild(panel);
    if (!launcher.isConnected) host.appendChild(launcher);
    setPanelOpen(false);          // stays closed until captions appear
    // Teams is a single-page app and re-renders large parts of the DOM; if it
    // removes our node, put it back.
    every(() => {
      const host2 = document.body || document.documentElement;
      if (!panel.isConnected) host2.appendChild(panel);
      if (!launcher.isConnected) host2.appendChild(launcher);
    }, 3000);
    console.log("[caption] panel mounted");
  }
  mountPanel();

  const $log  = panel.querySelector("#mct-log");
  const $meta = panel.querySelector("#mct-meta");
  const $file = panel.querySelector("#mct-file");
  const $dot   = panel.querySelector("#mct-dot");
  const $chips = panel.querySelector("#mct-speakers");
  const $sum   = panel.querySelector("#mct-summary");
  const $sumWho = panel.querySelector("#mct-sum-who");
  const $sumOut = panel.querySelector("#mct-sum-out");
  const $jump   = panel.querySelector("#mct-jump");

  /**
   * Follow the newest caption, unless the reader has scrolled back to look at
   * something.
   *
   * Every partial caption update repaints a row, and the old code scrolled to the
   * bottom on each one — several times a second while someone is talking. Scrolling
   * up to re-read a line was therefore impossible: you were dragged back down
   * before you could finish it.
   *
   * A scroll position is fractional and the content grows between frames, so
   * "at the bottom" has to be a tolerance, never an equality.
   */
  const STICK_PX = 40;
  let stick = true;

  function atBottom() {
    return $log.scrollHeight - $log.scrollTop - $log.clientHeight <= STICK_PX;
  }

  /** Scroll to the newest caption if we are still following it. */
  function toBottom(force = false) {
    if (force) stick = true;
    if (!stick) return;
    $log.scrollTop = $log.scrollHeight;
    $jump.style.display = "none";
  }

  $log.addEventListener("scroll", () => {
    stick = atBottom();
    // The pill is the way back. It appears the moment you leave the bottom, so
    // returning never means hunting for the scrollbar in a 380px-wide box.
    $jump.style.display = stick ? "none" : "block";
  });

  $jump.onclick = () => toBottom(true);

  const $settings = panel.querySelector("#mct-settings");
  const $lang     = panel.querySelector("#mct-lang");
  const $detected = panel.querySelector("#mct-detected");
  const $why         = panel.querySelector("#mct-why");
  const $filtered    = panel.querySelector("#mct-filtered");
  const $filteredTxt = panel.querySelector("#mct-filtered-txt");
  panel.querySelector("#mct-filtered-clear").onclick = () => setFilter("");

  // ---------- language ------------------------------------------------------

  /**
   * Pick a starting language for someone who has never chosen one.
   *
   * The browser's own language is the best guess available and is right most of
   * the time — a colleague in France has a French browser. Falling back to the
   * service's default would show everyone Persian, which is right for one person
   * and wrong for the rest.
   */
  function guessTarget(fallback) {
    for (const tag of (navigator.languages || [navigator.language || ""])) {
      if (!tag) continue;
      if (langs.byCode[tag]) return tag;                       // exact, e.g. zh-TW
      const base = tag.split("-")[0].toLowerCase();
      if (langs.byCode[base]) return base;                     // fr-CA -> fr
    }
    return fallback;
  }

  function buildPicker() {
    $lang.textContent = "";
    for (const l of langs.list) {
      // The endonym next to the English name: someone looking for their own
      // language scans for how they write it, not for how English spells it.
      const label = l.native && l.native !== l.name ? `${l.name} \u2014 ${l.native}` : l.name;
      $lang.appendChild(el("option", { value: l.code, text: label }));
    }
    if (prefs.target) $lang.value = prefs.target;
  }

  /**
   * Change the reader's language.
   *
   * Existing translations are cleared rather than re-translated. They are in the
   * previous language, so leaving them would make the panel a mix of two; and
   * re-translating what is on screen could be two hundred calls at the press of a
   * dropdown. New lines arrive in the new language, and the transcript file
   * already has the old ones.
   */
  async function setTarget(code, { persist = true } = {}) {
    if (!code || code === prefs.target) return;
    // A change before anyone has spoken separates nothing, so it gets no divider.
    const had = !!prefs.target && transcript.length > 0;
    prefs.target = code;
    if ($lang.value !== code) $lang.value = code;
    if (persist) await store.set(LANG_KEY, code);

    /*
     * What is already on screen is left alone.
     *
     * An earlier version cleared it, on the reasoning that a panel holding two
     * languages is inconsistent. That was wrong: those lines were translated,
     * they are correct, and throwing them away loses the part of the meeting the
     * reader most likely scrolled back to check. The saved transcript never did
     * this — it keeps the first ten in Italian and the rest in Persian — and the
     * panel should not disagree with the file.
     *
     * Each row already carries the script and direction of the language it was
     * translated into, set when its text arrived, so a mixed panel renders each
     * half correctly. A divider says where the change happened.
     */
    if (had) note(`Now translating into ${targetName()}`);

    applyPassthrough();
    paintDetected();
    paintStatus();
  }

  $lang.onchange = () => setTarget($lang.value);

  /** The translation lane's classes: direction and the script's font stack. */
  const trClass = (error = "", code = "") => {
    const row = langs.byCode[code || prefs.target] || null;
    return "mct-tr" + (row?.rtl ? " rtl" : "") + ` s-${row?.script || "latn"}`
         + (error ? " err" : "");
  };

  /**
   * Why there are no translations, when there are none.
   *
   * Both reasons look identical on screen — captions arriving with nothing
   * underneath them — and both used to be explained only by a clause in a small
   * grey footer. For someone whose run.sh window got closed, "translator offline
   * at http://127.0.0.1:8100" is not an instruction.
   *
   * The service being down does NOT hide the translation lane: it comes back on
   * its own, and the lane should be there when it does.
   */
  function applyPassthrough() {
    const pass = passthrough();
    panel.classList.toggle("passthrough", pass);

    const reason = !server.ok ? "offline" : (pass ? "pass" : "");
    panel.classList.toggle("why", !!reason);
    if (!reason) return;

    $why.textContent = "";
    if (reason === "offline") {
      $why.appendChild(el("span", { text: "The translation companion is not running, so "
                                        + "nothing is being translated. Start it with " }));
      $why.appendChild(el("b", { text: "server/run.sh" }));
      $why.appendChild(el("span", { text: " and leave that window open. Click here to "
                                        + "try again." }));
    } else {
      // Rebuilt each time so it names the languages currently in play.
      $why.appendChild(el("span", { text: "The captions are already in " }));
      $why.appendChild(el("b", { text: caption.name || caption.lang }));
      $why.appendChild(el("span", {
        text: ", which is the language you have chosen \u2014 so nothing is being "
            + "translated. Click here to pick a different one.",
      }));
    }
  }

  function paintDetected() {
    if (!caption.lang) {
      $detected.textContent = caption.tried
        ? "Could not tell what language the captions are in yet."
        : "Listening for a few lines to work out the caption language\u2026";
      return;
    }
    $detected.textContent = "";
    $detected.appendChild(el("span", { text: "Captions are in " }));
    $detected.appendChild(el("b", { text: caption.name || caption.lang }));
    $detected.appendChild(el("span", {
      text: passthrough()
        ? " \u2014 same as yours, so nothing is being translated."
        : ` \u2014 translating into ${targetName()}.`,
    }));
  }

  function openSettings() {
    $settings.classList.add("open");
    paintDetected();
  }

  panel.querySelector("#mct-gear").onclick = () => {
    $settings.classList.toggle("open");
    if ($settings.classList.contains("open")) paintDetected();
  };

  // The banner exists to be acted on, so it is the control as well as the notice.
  $why.onclick = () => { if (server.ok) openSettings(); else loadConfig(); };

  /**
   * Hiding the log and bringing it back.
   *
   * `display: none` discards an element's scroll position — the browser has no box
   * to keep it on. So switching to Summary and back dropped the reader at the
   * oldest caption in the log, which is what "the scroll disappeared" was.
   *
   * Both the position and whether we were following the newest line are saved,
   * because whichever of the two the reader had chosen is the one to restore.
   */
  let logScroll = 0, logStick = true;

  function hideLog() {
    if ($log.style.display === "none") return;   // already hidden; do not overwrite
    logScroll = $log.scrollTop;
    logStick  = stick;
    $log.style.display = "none";
  }

  /**
   * Whether the log is showing, decided in one place.
   *
   * Two controls hide it — the Summary tab and the collapse button — and the
   * collapse button used to keep its own idea of the state. A trip to Summary and
   * back left the two disagreeing: the log was expanded while the button still
   * offered to expand it, so the next press flipped only the flag and appeared to
   * do nothing at all. Deriving both from one place is what stops that.
   */
  let liveTab = true, collapsed = false;

  function applyLogVisibility() {
    if (liveTab && !collapsed) showLog(); else hideLog();
    const $hide = panel.querySelector("#mct-hide");
    $hide.textContent = collapsed ? "+" : "\u2013";
    // There is nothing to collapse while the Summary tab is up.
    $hide.style.display = liveTab ? "" : "none";
  }

  function showLog() {
    $log.style.display = "block";
    stick = logStick;
    // Only now that it has a box again: scrollTop on a hidden element is dropped.
    if (stick) toBottom(true);
    else { $log.scrollTop = logScroll; $jump.style.display = "block"; }
  }

  /**
   * Every settled segment, in order.
   *
   * Each record is {id, key, t, firstSeen, speaker, text, translation, saved}.
   * `id` is a plain counter rather than the caption key: Teams reuses caption
   * slots, so `key` repeats within a meeting and cannot identify a line in a file.
   * `saved` is what makes the file append-only — see flushTranscript.
   */
  const transcript = [];
  let segNo = 0;

  function meta(msg) { state.metaMsg = msg; paintStatus(); }

  /** One place that writes the footer, so capture state and translator state
   *  cannot fight over it. */
  function paintStatus() {
    const bits = [];
    if (state.metaMsg) bits.push(state.metaMsg);
    if (server.ok) {
      if (passthrough()) bits.push(`${caption.name} — not translating`);
      else if (targetName()) bits.push(`→ ${targetName()}`);
      if (server.inflight) bits.push(`translating ${server.inflight}…`);
      else if (server.lastMs) bits.push(`${Math.round(server.lastMs)}ms`);
    } else {
      bits.push(server.lastError || "translator offline");
    }
    $meta.textContent = bits.join(" · ");
    $dot.classList.toggle("live", !!state.container);
    $dot.classList.toggle("warn", !!state.container && !server.ok);
    // paintStatus runs on every change to the service's state, which makes it the
    // one place that reliably knows when the banner needs revisiting.
    applyPassthrough();
  }

  function trimLog() {
    while ($log.children.length > MAX_ROWS) {
      // Rows are dropped from the TOP, which pulls everything below it upwards.
      // For a reader scrolled back, that is the view jumping by a line every time
      // someone speaks. Take the removed height back out of the scroll position so
      // what they are reading stays where it is.
      const before = $log.scrollHeight;
      $log.firstChild.remove();
      if (!stick) $log.scrollTop = Math.max(0, $log.scrollTop - (before - $log.scrollHeight));
    }
  }

  function render(key, speaker, text, final) {
    let row = $log.querySelector(`[data-k="${CSS.escape(key)}"]`);
    if (!row) {
      row = el("div", { cls: "mct-seg" }, [
        el("div", { cls: "mct-spk" }),
        el("div", { cls: "mct-txt" }),
        el("div", { cls: trClass() }),
        el("div", { cls: "mct-lat" }),
      ]);
      row.dataset.k = key;
      $log.appendChild(row);
      trimLog();
    }
    const spk = row.querySelector(".mct-spk");
    spk.textContent = speaker || "";
    spk.style.color = colorFor(speaker);
    row.dataset.spk = speaker || "";
    // A row created while a filter is active must respect it immediately, or the
    // filtered view silently gains rows as people keep talking.
    row.style.display = (!speakerFilter || speakerFilter === speaker) ? "" : "none";
    const t = row.querySelector(".mct-txt");
    t.textContent = text;
    t.className = "mct-txt" + (final ? "" : " mct-live");
    toBottom();
  }

  /** Chips double as the colour key and the filter control. */
  function renderChips() {
    $chips.textContent = "";
    const names = [...bySpeaker.keys()].filter(Boolean);
    if (!names.length) return;

    const all = el("span", {
      cls: "mct-chip" + (speakerFilter ? "" : " on"),
      text: `All (${names.length})`,
    });
    all.onclick = () => setFilter("");
    $chips.appendChild(all);

    for (const n of names) {
      const c = el("span", {
        cls: "mct-chip" + (speakerFilter === n ? " on" : ""),
        text: `${n} (${bySpeaker.get(n).length})`,
      });
      c.style.color = colorFor(n);
      c.style.borderColor = colorFor(n);
      c.onclick = () => setFilter(speakerFilter === n ? "" : n);
      $chips.appendChild(c);
    }
  }

  function setFilter(name) {
    speakerFilter = name;
    for (const row of $log.querySelectorAll(".mct-seg")) {
      row.style.display = (!name || row.dataset.spk === name) ? "" : "none";
    }
    renderChips();
    paintFilter();
    toBottom(true);
  }

  /**
   * Say who is being hidden, for as long as they are hidden.
   *
   * This used to be a status-line message, and emit() rewrites that line on every
   * caption — so it lasted about a second. A filter set by a stray click on the
   * chip row (which sits directly above the log) then looked exactly like the tool
   * having stopped showing one person, with nothing on screen to explain it.
   */
  function paintFilter() {
    $filtered.classList.toggle("on", !!speakerFilter);
    if (speakerFilter) {
      $filteredTxt.textContent = `Showing only ${speakerFilter} — everyone else is hidden.`;
    }
  }

  /** Record what a speaker said, and keep the chips and dropdown in step. */
  function remember(speaker, text, revised) {
    const who = speaker || "";
    if (!bySpeaker.has(who)) bySpeaker.set(who, []);
    const arr = bySpeaker.get(who);
    if (revised && arr.length) arr[arr.length - 1] = text;
    else arr.push(text);
    renderChips();
    syncSpeakerOptions();
  }

  function syncSpeakerOptions() {
    const names = [...bySpeaker.keys()].filter(Boolean);
    const chosen = $sumWho.value;
    $sumWho.textContent = "";
    for (const n of names) {
      $sumWho.appendChild(el("option", { value: n, text: `${n} (${bySpeaker.get(n).length})` }));
    }
    if (names.includes(chosen)) $sumWho.value = chosen;
  }

  function renderTranslation(key, text, error = "", latency = "", lang = "") {
    // The transcript file wants the translation next to the original, and this is
    // the only place it arrives. Errors are not recorded: a line with no
    // translation is honest, one with "translator offline" written under it is not.
    if (!error && text) {
      const rec = transcript.findLast?.(r => r.key === key && !r.saved);
      if (rec) rec.translation = text;
    }
    const row = $log.querySelector(`[data-k="${CSS.escape(key)}"]`);
    if (!row) return;
    const tr = row.querySelector(".mct-tr");
    tr.textContent = error || text;
    // Styled for the language the TEXT is in, not the one currently selected. A
    // reply can land a second after the reader switched language, and dressing
    // Italian in a right-to-left Persian font is worse than either alone.
    tr.className = trClass(error, lang || prefs.target);
    row.querySelector(".mct-lat").textContent = latency;
    toBottom();
  }

  /**
   * Mark a change in the flow of the conversation — a language switch, either
   * the reader's or the meeting's.
   *
   * Goes into the transcript array alongside the caption lines, in order, so it
   * reaches the Markdown file in the right place. Everything above a divider is
   * in the previous language and stays that way.
   */
  function note(text) {
    const row = el("div", { cls: "mct-note" }, [
      el("span", { cls: "t", text: new Date().toLocaleTimeString() }),
      el("span", { text }),
    ]);
    $log.appendChild(row);
    trimLog();
    toBottom();

    transcript.push({
      id: String(++segNo), kind: "note", key: "", t: new Date().toISOString(),
      firstSeen: Date.now(), speaker: "", text, translation: "", saved: false,
    });
    console.log("[caption] --", text);
  }

  /** A segment stopped changing: record it, and ask for a translation. */
  function emit(key, speaker, text, revised = false) {
    if (!revised) state.emitted++;
    const record = () => transcript.push({
      id: String(++segNo), key, t: new Date().toISOString(),
      firstSeen: Date.now(), speaker, text, translation: "", saved: false,
    });
    if (revised) {
      // Only a record still on this side of the seal may be revised in place. One
      // already written to disk must not be silently edited in memory, or the panel
      // and the file would disagree with no way to tell which is right.
      const last = transcript.findLast?.(r => r.key === key && !r.saved);
      if (last) { last.text = text; last.revised = true; }
      else record();
    } else {
      record();
    }
    render(key, speaker, text, true);
    console.log(`[caption]${revised ? " (revised)" : ""}`, speaker ? speaker + ":" : "", text);

    // Context is the English history, not the translations.
    if (!revised) { recent.push(text); while (recent.length > 10) recent.shift(); }
    else if (recent.length) recent[recent.length - 1] = text;

    remember(speaker, text, revised);

    requestTranslation(key, speaker, text);
    const mins = Math.max((Date.now() - state.started) / 60000, 0.01);
    // "capture only" was true in phase 0 and has been wrong since translation
    // landed. A stale status line is worse than none — it tells the reader the
    // feature they are looking for does not exist yet.
    meta(`${state.emitted} segments · ${(state.emitted / mins).toFixed(1)}/min`);
  }

  // ---------- translation --------------------------------------------------

  /**
   * Per-line sequence numbers.
   *
   * A line can be revised while its first translation is still in flight, and
   * responses can come back out of order. Without a sequence check, a slow reply
   * for "What" can overwrite the newer, correct reply for "What country?" — the
   * reader then sees a translation that silently contradicts the caption above it.
   */
  const seqOf = new Map();

  async function loadConfig() {
    try {
      const r = await fetch(`${SERVER}/config`, { method: "GET" });
      if (!r.ok) throw new Error("HTTP " + r.status);
      const cfg = await r.json();
      server.ok = true;
      server.transcripts = !!cfg.transcript_enabled;

      if (Array.isArray(cfg.languages) && cfg.languages.length) {
        langs.list = cfg.languages;
        langs.byCode = Object.fromEntries(cfg.languages.map(l => [l.code, l]));
        // Cached so the picker still works while the service is unreachable -- the
        // list is static data, and a dropdown that empties itself when the service
        // blips looks broken.
        store.set("mct.languages", JSON.stringify(cfg.languages));
        buildPicker();
      }
      /*
       * Resolved once, in this order:
       *
       *   1. what this reader chose here before
       *   2. what the deployment configured, if it configured anything
       *   3. the browser's own language
       *   4. whatever the service reports as its default
       *
       * Step 2 exists because step 3 was doing real harm. A deployment with
       * TARGET_LANG=fa had every reader silently switched to their browser's
       * English -- which then matched the English captions, so pass-through
       * kicked in and translation stopped. Guessing is a reasonable default for
       * someone with no configuration; it must not overrule someone who has any.
       */
      if (!prefs.target) {
        const stored = await store.get(LANG_KEY);
        const pinned = cfg.target_lang_pinned && langs.byCode[cfg.target_lang]
          ? cfg.target_lang : "";
        await setTarget(
          (stored && langs.byCode[stored]) ? stored
            : (pinned || guessTarget(cfg.target_lang || "en")),
          { persist: false },
        );
      }
      // Shown before anything has been written, so the folder is discoverable from
      // the moment the panel opens rather than only after the first flush.
      if (cfg.transcript_dir) saved.dir = cfg.transcript_dir;
      server.lastError = "";
      paintFile();
      console.log("[caption] translator ready:", targetName(), targetRtl() ? "(RTL)" : "",
                  server.transcripts ? `| saving to ${saved.dir}` : "| not saving");
    } catch (e) {
      server.ok = false;
      server.lastError = `translator offline at ${SERVER}`;
      console.warn("[caption]", server.lastError, e.message);
    }
    paintStatus();
  }

  /**
   * Work out what language the captions are in — once, from the first real lines.
   *
   * Waits for enough text to be worth asking about. A detector fed four words
   * guesses, and a wrong guess here is expensive: it decides both the hint given
   * to the translator and whether this reader is translated for at all.
   */
  const DETECT_MIN_CHARS = 90;
  const DETECT_MAX_LINES = 6;
  // Lines between re-checks. A meeting's caption language can be changed
  // mid-call, and everything downstream quietly goes wrong when it is: the source
  // hint is for the wrong language, and a reader may be translated for when they
  // no longer need it, or not when they do. One call per few minutes of talking
  // is a small price for noticing.
  const DETECT_EVERY = 40;

  let sinceDetect = 0;

  async function maybeDetect(text) {
    if (caption.busy || !server.ok) return;

    caption.samples.push(text);
    while (caption.samples.length > DETECT_MAX_LINES) caption.samples.shift();

    if (caption.lang) {
      if (++sinceDetect < DETECT_EVERY) return;
      sinceDetect = 0;
    } else {
      const total = caption.samples.join(" ").length;
      if (total < DETECT_MIN_CHARS && caption.samples.length < DETECT_MAX_LINES) return;
    }

    caption.busy = true;
    caption.tried = true;
    try {
      const r = await fetch(`${SERVER}/detect`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ samples: caption.samples }),
      });
      const d = await r.json();
      if (d.lang && d.lang !== "und") {
        const changed = caption.lang && d.lang !== caption.lang;
        const first   = !caption.lang;
        caption.lang = d.lang;
        caption.name = d.name || d.lang;

        // Say so in the conversation, not just in the settings panel. Someone
        // scrolling back through a meeting that switched from English to Spanish
        // needs to know where that happened, and so does the saved transcript.
        if (changed) {
          note(passthrough()
            ? `Meeting captions changed to ${caption.name} \u2014 same as yours, not translating`
            : `Meeting captions changed to ${caption.name} \u2014 translating into ${targetName()}`);
        } else if (first && transcript.length) {
          note(passthrough()
            ? `Captions are in ${caption.name} \u2014 same as yours, not translating`
            : `Captions are in ${caption.name} \u2014 translating into ${targetName()}`);
        }
        console.log("[caption] captions are in", caption.name,
                    passthrough() ? "(same as yours - not translating)" : "");
      }
      // "und" is not fatal: the translator works without a source hint, it just
      // has less to go on, and more of the meeting may make the answer clear.
    } catch (e) {
      /* the next scheduled check will try again */
    } finally {
      caption.busy = false;
    }
    applyPassthrough();
    paintDetected();
    paintStatus();
  }

  async function requestTranslation(key, speaker, text) {
    if (!server.ok) return;

    maybeDetect(text);

    // The reader already speaks the meeting's language. The service would hand the
    // line straight back, so do not even ask: it is a round trip and a duplicate
    // line under every caption for no gain.
    if (passthrough()) return;

    const seq = (seqOf.get(key) || 0) + 1;
    seqOf.set(key, seq);

    // Pinned for the lifetime of this request. The reader may change language
    // while it is in flight, and the reply that comes back is a translation into
    // THIS language, not the new one.
    const asked = prefs.target;

    server.inflight++;
    paintStatus();
    try {
      const r = await fetch(`${SERVER}/translate`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          key, speaker, text,
          context: recent.slice(-CONTEXT_N),
          target: asked,
          // A hint, not an instruction. Empty until detection has run.
          source: caption.lang || undefined,
        }),
      });
      if (!r.ok) throw new Error("HTTP " + r.status);
      const d = await r.json();

      // A newer revision of this line has been sent since; discard this reply.
      if (seqOf.get(key) !== seq) return;

      if (d.error) {
        server.lastError = d.error;
        renderTranslation(key, "", d.error, "", asked);
      } else {
        server.lastError = "";
        server.lastMs = d.ms;
        renderTranslation(key, d.translation, "",
                          d.cached ? "cached" : `${Math.round(d.ms)}ms`, asked);
      }
    } catch (e) {
      server.ok = false;
      server.lastError = `translator unreachable — is it running on ${SERVER}?`;
      renderTranslation(key, "", server.lastError, "", asked);
    } finally {
      server.inflight--;
      paintStatus();
    }
  }

  // ---------- saving the transcript ----------------------------------------

  /**
   * A segment is written once it is *sealed*: it stopped changing long enough ago
   * that no revision and no translation is still coming for it. That is what lets
   * the file be pure append — nothing already on disk ever needs correcting.
   *
   * `force` ignores the seal. Used when the meeting ends or the tab is closing,
   * where losing the last few lines is worse than the small chance of writing one
   * before its translation lands.
   */
  function unsaved(force) {
    const now = Date.now();
    return transcript
      .filter(r => !r.saved && (force || now - r.firstSeen >= SEAL_MS))
      .slice(0, FLUSH_MAX);
  }

  async function flushTranscript(force = false) {
    // Only the top frame writes. content.js runs in every frame, and each frame
    // has its own SESSION — without this, an iframe that also sees captions would
    // start a second file for the same meeting.
    if (!IS_TOP || !server.transcripts) return;

    const batch = unsaved(force);
    if (!batch.length) {
      // Nothing outstanding means an earlier failure has since been made good, so
      // the warning must go — a stale "not saved" is worse than no message at all.
      if (!transcript.some(r => !r.saved)) saved.error = "";
      paintFile();
      return;
    }

    try {
      const r = await fetch(`${SERVER}/transcript`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        // Survives the page being closed, which is exactly when the last flush
        // happens. A plain fetch is cancelled on unload and the tail is lost.
        keepalive: true,
        body: JSON.stringify({
          session: SESSION,
          started_at: STARTED_AT,
          target_name: targetName(),
          segments: batch.map(r2 => ({
            id: r2.id, t: r2.t, speaker: r2.speaker,
            text: r2.text, translation: r2.translation,
            kind: r2.kind || "line",
          })),
        }),
      });
      if (!r.ok) throw new Error("HTTP " + r.status);
      const d = await r.json();
      if (d.error) throw new Error(d.error);

      for (const r2 of batch) r2.saved = true;
      saved.path = d.path;
      saved.dir = d.directory || saved.dir;
      saved.at = Date.now();
      saved.error = "";
    } catch (e) {
      // Leave the batch unsaved so the next flush retries it. Retrying cannot
      // duplicate: the service skips segment ids it has already written.
      saved.error = e.message || "could not save";
    }
    paintFile();
  }

  /** One line under the status, answering "where is my meeting being written?" */
  function paintFile() {
    if (!IS_TOP) return;
    if (!server.transcripts) { $file.textContent = ""; return; }

    if (saved.error) {
      $file.className = "err";
      $file.textContent = `not saved — ${saved.error}`;
      $file.title = "";
      return;
    }
    const where = saved.path || (saved.dir ? `${saved.dir}/${SESSION}.md` : "");
    if (!where) { $file.textContent = ""; return; }

    const waiting = transcript.filter(r => !r.saved).length;
    $file.className = "";
    $file.textContent = `\u{1F4C4} ${where}${waiting ? ` · ${waiting} not yet written` : ""}`;
    $file.title = "click to copy this path";
  }

  if (IS_TOP) {
    every(() => flushTranscript(), FLUSH_MS);

    // Closing the tab is the most likely way to lose the tail of a meeting, and
    // pagehide is the last event that reliably fires for it. visibilitychange
    // covers the case where the browser is killed without ever firing pagehide.
    addEventListener("pagehide", () => flushTranscript(true));
    document.addEventListener("visibilitychange", () => {
      if (document.visibilityState === "hidden") flushTranscript(true);
    });
  }

  // ---------- reading the caption DOM -------------------------------------

  /**
   * Teams renders each caption line as its own element. We identify a line by a
   * stable-ish key so revisions to the SAME line update in place instead of
   * appearing as new lines.
   */
  function keyFor(el, i) {
    return el.id || el.getAttribute("data-tid") || `idx-${i}`;
  }

  function speakerOf(el) {
    const s = el.querySelector('[data-tid*="author"], [class*="author"], [class*="speaker"]');
    return s ? s.textContent.trim() : "";
  }

  function textOf(el, speaker) {
    let t = (el.innerText || "").trim();
    if (speaker && t.startsWith(speaker)) t = t.slice(speaker.length).trim();
    return t.replace(/\s+/g, " ");
  }

  /**
   * Caption extraction, driven by Teams' own semantic attributes.
   *
   * Confirmed structure (Teams web, 2026-08-29):
   *
   *   <div class="___18l92v8 ...">                       one caption line
   *     <div>
   *       <span class="fui-ChatMessageCompact__author">
   *         <span data-tid="author">Mohamad Mokhtari</span>
   *     <div>
   *       <span data-tid="closed-caption-text">Welcome to this channel.</span>
   *
   * The class names are generated (`___18l92v8`, `fod5ikn`) and will change on any
   * Teams release. The `data-tid` values are semantic and are what Microsoft's own
   * tests hook into, so they are far more durable. We key off those exclusively and
   * treat everything else as decoration.
   */
  const TEXT_SEL   = '[data-tid="closed-caption-text"]';
  const AUTHOR_SEL = '[data-tid="author"]';

  /** Stable per-element ids. Teams mutates a line's text in place as the ASR
   *  revises, so identity must follow the NODE, not its content or its index —
   *  both of which change. A WeakMap also lets removed nodes be collected. */
  const nodeIds = new WeakMap();
  let nextId = 1;
  function idOf(el) {
    if (!nodeIds.has(el)) nodeIds.set(el, "L" + nextId++);
    return nodeIds.get(el);
  }

  /** From a caption-text span, walk up to the element that holds both it and the
   *  author span — that is one logical line. */
  function lineOf(textEl) {
    let el = textEl;
    for (let i = 0; i < 6 && el.parentElement; i++) {
      el = el.parentElement;
      if (el.querySelector(AUTHOR_SEL)) return el;
    }
    return textEl.parentElement || textEl;
  }

  function scan() {
    const root = state.container || document;
    let texts;
    try {
      texts = Array.from(root.querySelectorAll(TEXT_SEL));
      // The container itself may sit above a shadow boundary.
      if (!texts.length) texts = deepQueryAll(TEXT_SEL, root).filter(e => !isOurs(e));
    } catch { return; }

    texts.forEach((textEl) => {
      if (isOurs(textEl)) return;

      const line    = lineOf(textEl);
      const authorEl = line.querySelector(AUTHOR_SEL);
      const speaker = authorEl ? authorEl.textContent.trim() : "";
      const text    = (textEl.textContent || "").trim().replace(/\s+/g, " ");
      if (!text) return;

      const key  = idOf(line);
      const prev = state.pending.get(key);
      if (prev && prev.text === text) return;        // unchanged
      if (prev?.timer) clearTimeout(prev.timer);

      render(key, speaker, text, false);             // show at once, greyed

      // A line that has clearly finished is translated after the short window. One
      // that has not is held: any further speech resets this timer, so a sentence
      // being built up a few words at a time is translated once, at the end,
      // instead of once per pause.
      const wait = endsSentence(text) || !punctuates() ? SETTLE_MS : HOLD_MS;

      const timer = setTimeout(() => {
        const cur = state.pending.get(key);
        if (!cur) return;
        // A line can settle, then be revised again ("What" -> "What country?").
        // Emit the revision under the SAME key so downstream replaces rather than
        // appending a second, superseded translation.
        // Record whether this line ended cleanly, so `punctuates` can tell a
        // stream that has no punctuation from one that simply has not got there yet.
        punctHistory.push(endsSentence(cur.text));
        if (punctHistory.length > 40) punctHistory.shift();

        emit(key, cur.speaker, cur.text, cur.emitted);
        cur.emitted = true;
      }, wait);

      state.pending.set(key, { speaker, text, timer, emitted: prev?.emitted || false });
    });
  }

  function attach(el, how) {
    if (isOurs(el)) {
      meta("refused: that is this panel, not the Teams captions");
      console.warn("[caption] refused to attach to our own panel");
      return;
    }
    if (state.observer) state.observer.disconnect();
    state.container = el;
    state.observer = new MutationObserver(scan);
    state.observer.observe(el, { childList: true, subtree: true, characterData: true });
    $dot.classList.add("live");
    meta(`attached via ${how} — waiting for speech`);
    console.log("[caption] attached via", how, "->",
      `<${el.tagName.toLowerCase()}${el.id ? "#" + el.id : ""}` +
      `${el.className ? "." + String(el.className).split(/\s+/)[0] : ""}>`);
    scan();
  }

  /** Walk the DOM including open shadow roots. querySelector stops at a shadow
   *  boundary, so anything Teams renders in a web component is invisible to it. */
  function deepQueryAll(selector, root = document, out = [], depth = 0) {
    if (depth > 12) return out;
    try { out.push(...root.querySelectorAll(selector)); } catch { /* bad selector */ }
    const all = root.querySelectorAll ? root.querySelectorAll("*") : [];
    for (const el of all) {
      if (el.shadowRoot) deepQueryAll(selector, el.shadowRoot, out, depth + 1);
    }
    return out;
  }

  /** The observation root must hold every caption line. Attaching to one line's
   *  own div means later lines are never seen. */
  function captionRoot() {
    // deepQueryAll pierces open shadow roots; querySelector does not. Teams renders
    // parts of the meeting UI in web components, so the plain call finds nothing
    // even when the element is plainly there in the inspector.
    const wins = deepQueryAll('[data-tid="closed-caption-v2-window"]').filter(e => !isOurs(e));
    if (wins.length) return { el: wins[0], how: 'data-tid="closed-caption-v2-window"' };

    const texts = deepQueryAll(TEXT_SEL).filter(e => !isOurs(e));
    if (!texts.length) return null;

    // Every line, not just the first: whatever we attach to has to still be the
    // right element when the sixth person speaks.
    const lines = texts.map(lineOf);
    let root = commonAncestor(lines) || lines[0];
    // With a single line on screen -- which is the usual state the moment captions
    // first appear -- the common ancestor of "all lines" is that one line. Attaching
    // there would miss everything said afterwards, so step out to its container.
    if (lines.includes(root)) root = parentOf(root) || root;
    const shadow = root.getRootNode() !== document ? " (shadow DOM)" : "";
    return { el: root, how: `common ancestor of ${lines.length} caption line(s)${shadow}` };
  }

  function autoFind() {
    const root = captionRoot();
    if (root && !isOurs(root.el)) { attach(root.el, root.how); return true; }
    for (const sel of CANDIDATES) {
      const hits = deepQueryAll(sel);
      const el = hits.find(h => !isOurs(h) && (h.innerText || "").trim().length);
      if (el) { attach(el, sel + (el.getRootNode() !== document ? " (shadow DOM)" : "")); return true; }
    }
    return false;
  }

  /**
   * The diagnostic that actually solves this: say a word in the meeting, type it
   * here, and we report every element containing it — including inside shadow roots
   * and this frame's own document. That tells us the real selector instead of
   * guessing at Teams' obfuscated markup.
   */
  function findByText(needle) {
    const hits = [];
    const seen = new Set();
    const walk = (root, depth = 0) => {
      if (depth > 12) return;
      const all = root.querySelectorAll ? root.querySelectorAll("*") : [];
      for (const el of all) {
        if (el.shadowRoot) walk(el.shadowRoot, depth + 1);
        if (isOurs(el)) continue;                     // never match our own panel
        const txt = (el.textContent || "");
        if (!txt.toLowerCase().includes(needle.toLowerCase())) continue;
        // Keep the deepest elements — the ones whose children don't also match.
        const childMatch = Array.from(el.children).some(
          c => (c.textContent || "").toLowerCase().includes(needle.toLowerCase()));
        if (childMatch) continue;
        if (seen.has(el)) continue;
        seen.add(el);
        hits.push(el);
      }
    };
    walk(document);
    return hits;
  }
  window.__mctFindByText = findByText;

  /**
   * Is `node` inside `root`, crossing shadow boundaries?
   *
   * Element.contains stops at a shadow root, and deepQueryAll deliberately does
   * not — so a caption inside a shadow tree within our own container would look
   * like it was somewhere else entirely, and the check below would re-attach once
   * a second forever.
   */
  /** One step up, stepping out of a shadow root by way of its host. */
  const parentOf = (n) =>
    n.parentElement || (n.parentNode && n.parentNode.host) || n.host || null;

  function within(root, node) {
    let n = node;
    while (n) {
      if (n === root) return true;
      n = n.parentNode || n.host || null;   // .host steps out of a shadow root
    }
    return false;
  }

  /**
   * The nearest element containing all of these nodes.
   *
   * Needed because "the parent of the first caption line" is not the caption
   * area. Where Teams gives each line its own wrapper — and it does, on some
   * builds — that parent holds exactly one line, so everything anyone said after
   * the first sentence was outside the element being watched, and never seen.
   * The observer sat on a box that would never change again.
   */
  function commonAncestor(nodes) {
    let root = nodes[0];
    for (const n of nodes) {
      while (root && !within(root, n)) root = parentOf(root);
      if (!root) return null;
    }
    return root;
  }

  /**
   * Give up on the current caption element and go looking again.
   *
   * This is what a page reload does for capture, without the reload — which also
   * drops you out of the meeting and throws away the transcript.
   *
   * Pending settle timers belong to the element being abandoned, so they are
   * dropped rather than fired: the new container will present the same speech
   * under new keys, and emitting both would duplicate the last line or two.
   */
  function reattach(why) {
    console.log("[caption] re-attaching:", why);
    if (state.observer) { state.observer.disconnect(); state.observer = null; }
    for (const p of state.pending.values()) if (p.timer) clearTimeout(p.timer);
    state.pending.clear();
    state.container = null;
    $dot.classList.remove("live");
    lastReattach = Date.now();
    if (!autoFind()) meta(`re-attaching (${why})\u2026`);
  }

  let lastReattach = 0;

  /**
   * Keep looking, indefinitely.
   *
   * The previous version gave up after 120 tries (~2 minutes) and said so in the
   * footer. In practice a meeting starts, captions get switched on, people get
   * settled — and two minutes are gone before anyone speaks. The search had already
   * quit, so nothing was ever captured and the only way back was the manual picker.
   *
   * There is no reason to stop: the poll is a single querySelectorAll against a
   * page that is doing far heavier work anyway. It just slows down after the first
   * minute so an idle tab is not scanning every second all day.
   *
   * It also re-attaches. Teams re-renders large parts of the DOM — leaving a call,
   * rejoining, toggling captions off and on — and the element we were observing can
   * be detached without warning. Watching a node that is no longer in the document
   * fails silently, which looks exactly like "captions stopped working".
   */
  let tries = 0;
  let captionsWere = false;   // previous poll, so we can act on the change, not the state
  every(() => {
    tries++;

    // Are captions on screen right now?
    const captionsOn = deepQueryAll(TEXT_SEL).some(e => !isOurs(e));

    if (captionsOn !== captionsWere) {
      // Captions were switched on or off. That is a change in the world, so the
      // user's earlier override no longer applies and automatic behaviour resumes.
      // Without this, dismissing the panel once would silently disable the tool
      // for the rest of the day and nobody would know why it stopped appearing.
      captionsWere = captionsOn;
      override = null;
      if (!captionsOn) flushTranscript(true);   // a caption session just ended
    }

    // Follow the captions unless the user has said otherwise.
    const shouldBeOpen = override ? override === "open" : captionsOn;
    if (shouldBeOpen !== panelOpen) setPanelOpen(shouldBeOpen);

    if (state.container) {
      // Gone from the page entirely. Unambiguous, so act at once.
      if (!state.container.isConnected) {
        meta("caption panel was replaced \u2014 re-attaching\u2026");
        reattach("container removed");
        return;
      }

      /*
       * Attached to the wrong element.
       *
       * The old check asked whether our container still HELD caption text, and
       * treated that as proof it was still the live one. It is not: Teams can
       * start writing captions into a new element while the old one stays in the
       * page with its last few lines still in it. That reads as healthy forever,
       * so the panel went quiet and only reloading the page brought it back —
       * which also drops you out of the meeting.
       *
       * Caption text somewhere we are NOT watching is the actual signal.
       */
      const stray = deepQueryAll(TEXT_SEL)
        .filter(e => !isOurs(e) && !within(state.container, e));

      // Rate-limited: if autoFind picks the same wrong element again this would
      // otherwise re-attach every second for the rest of the meeting.
      if (stray.length && Date.now() - lastReattach > 5000) {
        meta("captions moved \u2014 re-attaching\u2026");
        reattach("captions moved");
        return;
      }
      if (stray.length) return;   // waiting out the backoff

      const alive = state.container.querySelector(TEXT_SEL) ||
                    deepQueryAll(TEXT_SEL, state.container).length ||
                    state.pending.size;
      if (alive) return;
      meta("caption panel changed \u2014 re-attaching\u2026");
      reattach("container went empty");
      return;
    }

    if (autoFind()) return;

    // After the first minute, only scan every third tick — captions are usually
    // on within seconds of someone speaking, and an idle tab should stay idle.
    if (tries > 60 && tries % 3 !== 0) return;

    if (tries % 5 === 0) {
      const seen = deepQueryAll(TEXT_SEL).length;
      meta(seen
        ? `found ${seen} caption node(s) but could not attach — try "find text"`
        : `waiting for captions… turn on live captions in Teams`);
    }
  }, 1000);

  // ---------- manual picker (the fallback that makes this robust) ----------

  panel.querySelector("#mct-pick").onclick = () => {
    meta("click the caption text in the meeting…");
    document.body.id = "mct-picking";
    const once = (ev) => {
      if (panel.contains(ev.target)) return;
      ev.preventDefault(); ev.stopPropagation();
      document.body.removeAttribute("id");
      document.removeEventListener("click", once, true);
      // Go up a couple of levels: the clicked node is usually one line, and we
      // want the container that holds all of them.
      let el = ev.target;
      for (let i = 0; i < 3 && el.parentElement; i++) el = el.parentElement;
      attach(el, "manual pick");
    };
    document.addEventListener("click", once, true);
  };

  panel.querySelector("#mct-diag").onclick = () => {
    const needle = prompt(
      "Type a word you just SAW in the Teams caption (e.g. Hello).\n" +
      "We'll locate the element containing it and attach to its container."
    );
    if (!needle) return;
    const hits = findByText(needle);
    console.log("[caption] matches for", JSON.stringify(needle), "=",
      hits.map(h => `<${h.tagName.toLowerCase()}${h.className ? "." +
        String(h.className).split(/\s+/)[0] : ""}> "${(h.innerText||"").trim().slice(0,50)}"`));
    if (!hits.length) {
      meta(`"${needle}" not found in this frame — captions may be in an iframe. See console.`);
      return;
    }
    // The caption line is the deepest match; its container is a level or two up.
    // One level up from the deepest match: enough to include the speaker node,
    // not enough to reach the ancestor that concatenates every line.
    let el = hits[hits.length - 1];
    if (el.parentElement) el = el.parentElement;
    if (el.parentElement) el = el.parentElement;   // container of the line elements
    attach(el, `found via text "${needle}"`);
    meta(`attached via text search (${hits.length} matches) — check console for details`);
  };

  /** Print the attached container's structure so selectors can be tuned against
   *  what Teams actually renders, instead of guesses. */
  // ---- tabs ---------------------------------------------------------------
  const $tabLive = panel.querySelector("#mct-tab-live");
  const $tabSum  = panel.querySelector("#mct-tab-sum");

  function showTab(which) {
    const live = which === "live";
    $tabLive.classList.toggle("on", live);
    $tabSum.classList.toggle("on", !live);
    // Explicit values, not "".
    //
    // Clearing an inline style falls back to the stylesheet, and the stylesheet says
    // `#mct-summary { display: none }` because it starts hidden. So `= ""` re-hid the
    // panel it was meant to reveal, and the tab appeared to do nothing at all.
    //
    // #mct-speakers is the exception: it keeps "" on purpose, so the `:empty` rule
    // can still hide the chip row before anyone has spoken. An inline value would
    // override that and leave an empty strip.
    liveTab = live;
    // Clicking "Live" is a request to see the captions, so it also un-collapses.
    // Arriving at the Live tab to find an empty box and a small "+" is the same
    // showing-less-without-saying-why that the filter and pass-through banners
    // exist to prevent.
    if (live) collapsed = false;
    applyLogVisibility();
    $chips.style.display = live ? "" : "none";
    $sum.style.display   = live ? "none" : "flex";
    if (!live) syncSpeakerOptions();
  }
  $tabLive.onclick = () => showTab("live");
  $tabSum.onclick  = () => showTab("summary");
  showTab("live");

  // ---- maximise / restore --------------------------------------------------
  /**
   * Three sizes, cycled by one button.
   *
   *   small  glance at it while watching the meeting   (the default)
   *   large  read along with it                        (620px)
   *   full   the conversation IS what you are doing    (covers the page)
   *
   * A cycle rather than a fourth button: the header already carries nine, and the
   * three are points on one axis, not three unrelated choices. The tooltip names
   * the next one so the button does not have to be guessed at.
   */
  const SIZES = ["small", "large", "full"];
  let sizeIx = 0;
  const $max = panel.querySelector("#mct-max");

  function setSize(ix) {
    sizeIx = (ix % SIZES.length + SIZES.length) % SIZES.length;
    const mode = SIZES[sizeIx];

    // Dragging writes left/top/right/bottom, the native resize handle writes
    // width/height, and an inline style beats a class. Without clearing them, the
    // size classes do nothing at all once the panel has been moved or resized —
    // which is exactly when someone reaches for a bigger view.
    for (const prop of ["left", "top", "right", "bottom", "width", "height"]) {
      panel.style[prop] = "";
    }
    panel.classList.toggle("max",  mode === "large");
    panel.classList.toggle("full", mode === "full");
    $max.title = `${mode} \u2014 click for ${SIZES[(sizeIx + 1) % SIZES.length]}`;
    toBottom();
  }

  $max.onclick = () => setSize(sizeIx + 1);
  setSize(0);

  // Escape leaves full screen. At that size the panel covers Teams completely, so
  // this is the only obvious way out — and it is what every full-screen view does.
  // Not preventDefault: Teams may want the key too, and only full screen is ours.
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && SIZES[sizeIx] === "full") setSize(0);
  });

  // ---- summary -------------------------------------------------------------
  panel.querySelector("#mct-sum-go").onclick = async () => {
    const who = $sumWho.value;
    const segments = bySpeaker.get(who) || [];
    if (!who || !segments.length) { $sumOut.textContent = "Nothing recorded for that speaker yet."; return; }
    if (!server.ok) { $sumOut.textContent = "Translator offline — start the local service."; return; }

    $sumOut.className = "mct-sum-out";
    $sumOut.textContent = `Summarising ${segments.length} segments from ${who}…`;
    try {
      const r = await fetch(`${SERVER}/summarize`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ speaker: who, segments, target: prefs.target }),
      });
      if (!r.ok) throw new Error("HTTP " + r.status);
      const d = await r.json();
      if (d.error) {
        $sumOut.className = "mct-sum-out err";
        $sumOut.textContent = d.error;
        return;
      }
      // Summaries are long-form prose; RTL matters even more here than for a
      // single caption line.
      $sumOut.className = `mct-sum-out${targetRtl() ? " rtl" : ""} s-${targetScript()}`;
      $sumOut.textContent = d.summary;
      meta(`summarised ${d.segments} segments · ${Math.round(d.ms)}ms`);
    } catch (e) {
      $sumOut.className = "mct-sum-out err";
      $sumOut.textContent = `Could not reach the translator at ${SERVER}`;
    }
  };

  panel.querySelector("#mct-close").onclick = () => setPanelOpen(false, /*byUser=*/true);

  // Forces a write, seal and all. The timer handles the normal case; this is for
  // when you are about to close the laptop and want to be sure.
  panel.querySelector("#mct-save").onclick = async () => {
    if (!server.transcripts) { meta("the companion is not saving transcripts"); return; }
    const n = transcript.filter(r => !r.saved).length;
    await flushTranscript(true);
    meta(saved.error ? `could not save — ${saved.error}` : `wrote ${n} segments`);
  };

  // The path is long and unselectable inside a panel you cannot easily highlight
  // in, so clicking it copies rather than trying to make it selectable.
  $file.onclick = () => {
    const path = saved.path || (saved.dir ? `${saved.dir}/${SESSION}.md` : "");
    if (!path) return;
    navigator.clipboard.writeText(path).then(
      () => meta("transcript path copied"),
      () => meta(path),
    );
  };

  /**
   * What the reload used to be for.
   *
   * This button only re-checked the translation service, which was almost never
   * the thing that had failed — so pressing it when captions stopped did nothing
   * visible, and the only cure left was reloading the page and rejoining the
   * meeting. It now does both halves: drop the caption element and hunt for it
   * again, and re-check the service.
   */
  panel.querySelector("#mct-retry").onclick = () => {
    lastReattach = 0;                    // an explicit press ignores the backoff
    reattach("asked to");
    loadConfig();
    meta(state.container ? "reconnected" : "looking for captions\u2026");
  };

  panel.querySelector("#mct-dump").onclick = () => {
    if (!state.container) { meta("not attached yet"); return; }
    const tree = (node, d = 0) => {
      if (d > 6) return "";
      const pad = "  ".repeat(d);
      const cls = (node.className || "").toString().slice(0, 60);
      const own = Array.from(node.childNodes)
        .filter(n => n.nodeType === 3).map(n => n.textContent.trim()).join(" ").slice(0, 70);
      let s = `${pad}<${node.tagName.toLowerCase()}`
            + (node.id ? ` id="${node.id}"` : "")
            + (cls ? ` class="${cls}"` : "")
            + (node.getAttribute("data-tid") ? ` data-tid="${node.getAttribute("data-tid")}"` : "")
            + `>` + (own ? `  "${own}"` : "") + "\n";
      for (const c of node.children) s += tree(c, d + 1);
      return s;
    };
    const dump = tree(state.container);
    console.log("[caption] STRUCTURE ----\n" + dump);
    navigator.clipboard.writeText(dump).then(
      () => meta("structure copied to clipboard — paste it back"),
      () => meta("structure printed to console")
    );
  };

  panel.querySelector("#mct-copy").onclick = () => {
    const txt = transcript.map(r => r.kind === "note"
      ? `\n-- ${r.text} --\n`
      : `${r.t} ${r.speaker ? r.speaker + ": " : ""}${r.text}`).join("\n");
    navigator.clipboard.writeText(txt).then(() => meta(`copied ${transcript.length} segments`));
  };

  panel.querySelector("#mct-hide").onclick = () => {
    collapsed = !collapsed;
    applyLogVisibility();
  };

  // Drag by the header — the panel will otherwise cover something important.
  (() => {
    const head = panel.querySelector("#mct-head");

    const DRAG_PX = 3;    // below this the pointer wobbled; it was a click
    const KEEP_PX = 120;  // this much of the panel always stays on screen

    let sx, sy, ox, oy, pw, armed = false, moving = false;

    head.addEventListener("mousedown", (e) => {
      if (e.target.tagName === "BUTTON") return;
      if (SIZES[sizeIx] === "full") return;    // it covers the page; nowhere to move it

      const r = panel.getBoundingClientRect();
      sx = e.clientX; sy = e.clientY;
      ox = r.left;    oy = r.top;
      pw = r.width;                            // measured once, or the clamp feeds back
      armed = true; moving = false;
      e.preventDefault();
      // Deliberately no style change here. See the comment in mousemove.
    });

    document.addEventListener("mousemove", (e) => {
      if (!armed) return;
      const dx = e.clientX - sx, dy = e.clientY - sy;

      if (!moving) {
        if (Math.abs(dx) < DRAG_PX && Math.abs(dy) < DRAG_PX) return;
        moving = true;

        /*
         * Re-anchor from the bottom-right corner to explicit coordinates.
         *
         * This has to happen on the first real movement, NOT on mousedown. The
         * panel is anchored with right/bottom and no left/top; clearing right and
         * bottom before setting left and top leaves all four insets auto, and a
         * fixed element with four auto insets falls to its *static* position —
         * the end of <body>, off the bottom of the page.
         *
         * A single click on the header therefore made the panel vanish, with no
         * way back short of reloading, which also throws away the transcript.
         */
        panel.style.right  = "auto";
        panel.style.bottom = "auto";
        panel.style.left   = ox + "px";
        panel.style.top    = oy + "px";
      }

      // Keep enough of it on screen to grab again. Dragged fully outside the
      // viewport the header is unreachable, and that is the same lost panel by a
      // slower route.
      const x = Math.min(Math.max(ox + dx, KEEP_PX - pw), innerWidth - KEEP_PX);
      const y = Math.min(Math.max(oy + dy, 0), innerHeight - 32);
      panel.style.left = x + "px";
      panel.style.top  = y + "px";
    });

    document.addEventListener("mouseup", () => { armed = false; moving = false; });
  })();

  /**
   * Restore the reader's language before anything else.
   *
   * The list and the choice both come from storage first, so the picker is
   * populated and correct even while the service is unreachable. Waiting for
   * /config would show an empty dropdown to anyone who opened the panel before
   * starting the companion, which reads as broken rather than as not-yet-ready.
   */
  (async () => {
    try {
      const cached = JSON.parse((await store.get("mct.languages")) || "null");
      if (Array.isArray(cached) && cached.length) {
        langs.list = cached;
        langs.byCode = Object.fromEntries(cached.map(l => [l.code, l]));
        buildPicker();
      }
    } catch (e) { /* a bad cache is not worth failing to start over */ }

    const stored = await store.get(LANG_KEY);
    if (stored && langs.byCode[stored]) await setTarget(stored, { persist: false });

    loadConfig();
  })();

  // The companion is a separate process the user starts by hand; poll until it
  // appears rather than making them reload the page.
  every(() => { if (!server.ok) loadConfig(); }, 15000);

  window.__mctCleanup = () => {
    if (state.observer) state.observer.disconnect();
    for (const t of timers) clearInterval(t);
    document.querySelectorAll("#mct-panel, #mct-launcher").forEach(n => n.remove());
  };

  console.log(
    "[caption] loaded |", IS_TOP ? "TOP frame" : "iframe:" + location.href.slice(0, 80),
    "| helper: __mctFindByText('hello')"
  );
})();
